//! Hack HD Antialiased Font — 20×40 high-resolution glyph data for KnoxOS
//!
//! Each pixel is an 8-bit alpha coverage value (0=transparent, 255=opaque).
//! Generated by rasterizing Hack-Regular.ttf at 4× supersample resolution
//! then box-downsampling for exact area-coverage antialiasing.
//!
//!   HD: 20×40 pixels (used for scale ≥ 2, giving 4× the detail of 10×20)
pub const GLYPH_WIDTH_HD: usize = 20;
pub const GLYPH_HEIGHT_HD: usize = 40;

pub fn get_glyph_hd(ch: char) -> Option<&'static [[u8; GLYPH_WIDTH_HD]; GLYPH_HEIGHT_HD]> {
    let idx = ch as usize;
    if (0x20..=0x7E).contains(&idx) {
        Some(&HACK_AA_HD[idx - 0x20])
    } else {
        None
    }
}

